func BuildWithDir(rawStages []map[string]interface{}, dir string) ([]Stage, error) {
        stages := make([]Stage, 0, len(rawStages))
        for i, sm := range rawStages {
                typ, ok := getString(sm, "type")
                if !ok || typ == "" {
                        return nil, fmt.Errorf("config: stage %d: type is required", i+1)
                }

                var st Stage
                var err error
                switch typ {
                case "filter":
                        st, err = buildFilter(i+1, sm)
                case "project":
                        st, err = buildProject(i+1, sm)
                case "sort":
                        st, err = buildSort(i+1, sm)
                case "limit":
                        st, err = buildLimit(i+1, sm)
                case "group":
                        st, err = buildGroup(i+1, sm)
                case "join":
                        st, err = buildJoin(i+1, sm, dir)
                case "dedup":
                        st, err = buildDedup(i+1, sm)
                case "pivot":
                        st, err = buildPivot(i+1, sm)
                case "unpivot":
                        st, err = buildUnpivot(i+1, sm)
                default:
                        return nil, fmt.Errorf("config: stage %d: unknown stage type %q", i+1, typ)
                }
                if err != nil {
                        return nil, err
                }
                stages = append(stages, st)
        }
        return stages, nil
}

