package record

type Record struct {
        Order    []string
        Values   map[string]string
        InputRow int
}

func New() *Record {
        return &Record{
                Order:  []string{},
                Values: map[string]string{},
        }
}

func (r *Record) Set(key, val string) {
        if _, ok := r.Values[key]; !ok {
                r.Order = append(r.Order, key)
        }
        r.Values[key] = val
}

func (r *Record) Get(key string) (string, bool) {
        v, ok := r.Values[key]
        return v, ok
}

