func buildBucket(idx int, sm map[string]interface{}) (Stage, error) {
        column, ok := getString(sm, "column")
        if !ok || column == "" {
                return nil, fmt.Errorf("config: stage %d: bucket: column must be a non-empty string", idx)
        }
        into, ok := getString(sm, "into")
        if !ok || into == "" {
                return nil, fmt.Errorf("config: stage %d: bucket: into must be a non-empty string", idx)
        }
        if into == column {
                return nil, fmt.Errorf("config: stage %d: bucket: into must differ from column", idx)
        }

        inclusive, ok := getString(sm, "inclusive")
        if !ok || inclusive == "" {
                inclusive = "right"
        }
        if inclusive != "left" && inclusive != "right" {
                return nil, fmt.Errorf("config: stage %d: bucket: inclusive must be left or right", idx)
        }

        onMissing, ok := getString(sm, "on_missing")
        if !ok || onMissing == "" {
                onMissing = "keep_empty"
        }
        if onMissing != "keep_empty" && onMissing != "drop" && onMissing != "error" {
                return nil, fmt.Errorf("config: stage %d: bucket: on_missing must be keep_empty, drop, or error", idx)
        }

        onNonNumeric, ok := getString(sm, "on_non_numeric")
        if !ok || onNonNumeric == "" {
                onNonNumeric = "error"
        }
        if onNonNumeric != "error" && onNonNumeric != "drop" && onNonNumeric != "keep_empty" {
                return nil, fmt.Errorf("config: stage %d: bucket: on_non_numeric must be error, drop, or keep_empty", idx)
        }

        _, hasEdges := sm["edges"]
        _, hasWidth := sm["width"]
        if hasEdges == hasWidth {
                return nil, fmt.Errorf("config: stage %d: bucket: exactly one of edges or width is required", idx)
        }

        var (
                edges       []float64
                labelCount  int
                autoLabels  []string
                underAuto   string
                overAuto    string
        )

        if hasWidth {
                widthRaw, ok := sm["width"]
                if !ok {
                        return nil, fmt.Errorf("config: stage %d: bucket: exactly one of edges or width is required", idx)
                }
                wm, ok := widthRaw.(map[string]interface{})
                if !ok {
                        return nil, fmt.Errorf("config: stage %d: bucket: width must be a mapping", idx)
                }
                for k := range wm {
                        if k != "step" && k != "start" && k != "count" {
                                return nil, fmt.Errorf("config: stage %d: bucket: unknown key %s in width", idx, k)
                        }
                }

                stepStr, ok := getString(wm, "step")
                if !ok || stepStr == "" {
                        return nil, fmt.Errorf("config: stage %d: bucket: width.step must be a positive finite number", idx)
                }
                step, err := parseFloat(stepStr)
                if err != nil || math.IsNaN(step) || math.IsInf(step, 0) || step <= 0 {
                        return nil, fmt.Errorf("config: stage %d: bucket: width.step must be a positive finite number", idx)
                }

                start := 0.0
