                        var err error
                        start, err = parseFloat(startStr)
                        if err != nil || math.IsNaN(start) || math.IsInf(start, 0) {
                                return nil, fmt.Errorf("config: stage %d: bucket: width.start must be a finite number", idx)
                        }
                }

                countStr, ok := getString(wm, "count")
                if !ok || countStr == "" {
                        return nil, fmt.Errorf("config: stage %d: bucket: width.count must be a positive integer", idx)
                }
                countI, err := strconv.Atoi(countStr)
                if err != nil || countI < 1 {
                        return nil, fmt.Errorf("config: stage %d: bucket: width.count must be a positive integer", idx)
                }

