                }
                list, ok := edgesRaw.([]interface{})
                if !ok {
                        return nil, fmt.Errorf("config: stage %d: bucket: edges must have at least two entries", idx)
                }
                if len(list) < 2 {
                        return nil, fmt.Errorf("config: stage %d: bucket: edges must have at least two entries", idx)
                }
                edges = make([]float64, 0, len(list))
                for i, item := range list {
                        es, ok := item.(string)
