                        }
                        if seen[ls] {
                                return nil, fmt.Errorf("config: stage %d: bucket: labels has duplicate entry %s", idx, ls)
                        }
                        seen[ls] = true
                        labels[i] = ls
                }
        }

        underLabel := underAuto
        if s, ok := getString(sm, "under_label"); ok {
                if s == "" {
                        return nil, fmt.Errorf("config: stage %d: bucket: under_label must be a non-empty string", idx)
