        }

        return &BucketStage{
                column:        column,
                into:          into,
                edges:        edges,
                labels:       labels,
                underLabel:   underLabel,
                overLabel:    overLabel,
                inclusive:    inclusive,
                onMissing:    onMissing,
                onNonNumeric: onNonNumeric,
        }, nil
}

func (s *BucketStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
        out := make([]*record.Record, 0, len(in))
