}

func (s *BucketStage) bucketLabel(v float64) string {
        first := s.edges[0]
        last := s.edges[len(s.edges)-1]
        if s.inclusive == "right" {
                if v <= first {
                        return s.underLabel
                }
                if v > last {
                        return s.overLabel
                }
                for i := 0; i < len(s.edges)-1; i++ {
                        if v > s.edges[i] && v <= s.edges[i+1] {
                                return s.labels[i]
                        }
                }
        } else {
                if v < first {
                        return s.underLabel
                }
                if v >= last {
                        return s.overLabel
                }
                for i := 0; i < len(s.edges)-1; i++ {
                        if v >= s.edges[i] && v < s.edges[i+1] {
                                return s.labels[i]
                        }
                }
        }
        return s.overLabel
}

func formatBucketFloat(f float64) string {
        if f == math.Trunc(f) && !math.IsInf(f, 0) && math.Abs(f) < 1e15 {
                return strconv.FormatInt(int64(f), 10)
        }
        return strconv.FormatFloat(f, 'g', -1, 64)
}

